- Exact Python 3.8 support remains unresolved rather than silently claimed via the new shared dependency floor.
- No CatchFn PR, push, release or deployment has been performed. TestFn's native Safari and historical-engine gates remain open in PR57's readiness record.
/**
 * Kysely adapter
 *
 * Maps the Superfunctions Adapter interface to Kysely query builder.
 * Kysely is a type-safe SQL query builder for TypeScript.
 */

import type {
  Adapter,
  AdapterSchemaInput,
  AdapterImplementation,
  CreateParams,
  FindOneParams,
  FindManyParams,
  UpdateParams,
  DeleteParams,
  CreateManyParams,
  UpdateManyParams,
  DeleteManyParams,
  UpsertParams,
  CountParams,
  WhereClause,
  OrderBy,
} from '../../adapter/types.js';
import { createAdapterFactory } from '../../adapter/factory.js';
import { NotFoundError, OperationNotSupportedError } from '../../adapter/errors.js';
import { createKyselyInternalCrud } from './internal.js';
import { normalizeAdapterSchema } from '../../adapter/schema-codecs.js';

export type KyselyDialect = 'postgres' | 'mysql' | 'sqlite';

export interface KyselyAdapterConfig {
  db: any; // Kysely instance
  dialect: KyselyDialect;
  schema: Record<string, string>; // model name -> table name
  /**
   * @deprecated Function authors should wrap incoming adapters with
   * `wrapWithSchema(adapter, getSchema(...))` inside their create/init function.
   * This option remains for compatibility and app-level direct adapter usage.
   */
  adapterSchema?: AdapterSchemaInput;
  schemaVersionsTable?: string; // optional table name for schema versions
  namespace?: any;
  debug?: boolean;
}

/**
 * Escape SQL LIKE wildcards to prevent SQL injection
 * Escapes % and _ characters that have special meaning in LIKE patterns
 */
function escapeLikeWildcards(value: string): string {
  return value.replace(/[%_]/g, '\\$&');
}

/**
 * Apply where clauses to Kysely query builder
 */
/**
 * Build a single Kysely expression for one WHERE clause.
 */
function buildClauseExpression(eb: any, clause: WhereClause): any {
  const { field, operator, value } = clause;

  switch (operator) {
    case 'eq':
      return value === null ? eb(field, 'is', null) : eb(field, '=', value);
    case 'ne':
      return value === null ? eb(field, 'is not', null) : eb(field, '!=', value);
    case 'gt':
      return eb(field, '>', value);

