import type {
  Bot,
  BotConfig,
  BotStatus,
  Calendar,
  ChatMessage,
  MeetingMetadata,
  Participant,
  Platform,
  Recording,
  Transcript,
  Webhook,
} from '@recfn/core';

export interface RecFnStoreCapabilities {
  durable: boolean;
  backend: 'memory' | 'db';
  adapterName: string;
}

export interface ListOptions {
  limit?: number;
  cursor?: string;
}

export interface ListBotsOptions extends ListOptions {
  status?: BotStatus;
  platform?: Platform;
}

export interface ListResult<T> {
  items: T[];
  nextCursor?: string;
}

export interface CreateBotInput {
  meetingUrl: string;
  platform: Platform;
  config: Required<BotConfig>;
  namespace: string;
}

export interface RecFnStore {
  readonly capabilities: RecFnStoreCapabilities;

  createBot(input: CreateBotInput): Promise<Bot>;
  getBot(id: string, namespace: string): Promise<Bot | null>;
  listBots(namespace: string, opts: ListBotsOptions): Promise<ListResult<Bot>>;
