    transformInput: async (data, _model, action) => {
      let transformed = { ...data };

      // Apply key mapping (e.g., id -> _id for MongoDB)
      if (config.mapKeysInput) {
        for (const [from, to] of Object.entries(config.mapKeysInput)) {
