import type { RecFnStore } from '../store/types.js';
import type { WebhookPayload } from '../webhooks/events.js';
import {
  deliverWebhook,
  type WebhookDelivererDeps,
} from '../webhooks/deliver.js';
import type { MetricsEmitter } from './watchfn.js';
import { emitWebhookDelivery } from '../observability/metrics.js';

export interface PlugFnWebhookDeps {
  store: RecFnStore;
  fetch?: typeof globalThis.fetch;
  maxRetries?: number;
  metrics?: MetricsEmitter;
}

/**
 * Deliver a webhook event to all configured webhooks for the namespace
 * that subscribe to this event type.
 * Uses plugfn-style delivery: HMAC signing, retry on failure (at-least-once).
 */
export async function deliverWebhookEvent(
  namespace: string,
  eventType: string,
  payload: WebhookPayload,
  deps: PlugFnWebhookDeps,
): Promise<void> {
  const webhooks = await deps.store.listWebhooks(namespace);
  const matching = webhooks.filter((wh) => wh.events.includes(eventType));
  if (matching.length === 0) return;

  const deliverDeps: WebhookDelivererDeps = {
    fetch: deps.fetch,
    maxRetries: deps.maxRetries,
  };

  const results = await Promise.allSettled(
    matching.map((wh) =>
      deliverWebhook(
        { url: wh.url, secret: wh.secret },
        { ...payload, event: eventType as WebhookPayload['event'] },
        deliverDeps,
      ),
    ),
  );

  if (deps.metrics) {
    for (const result of results) {
      const ok = result.status === 'fulfilled' && result.value.ok;
      const attempt = result.status === 'fulfilled' ? result.value.attempt : undefined;
      emitWebhookDelivery(deps.metrics, {
        eventType,
        ok,
        attempt,
        namespace,
      });
    }
  }
  // Don't throw on delivery failure - at-least-once means we attempted; caller continues
}
import { deliverWebhook as deliverWithSharedPackage } from '@superfunctions/webhooks';
import type { WebhookPayload } from './events.js';

const RECFN_SIGNATURE_HEADER = 'X-RecFn-Signature';

const DEFAULT_RETRY_ATTEMPTS = 3;

export interface WebhookDelivererDeps {
  fetch?: typeof globalThis.fetch;
  maxRetries?: number;
}

export interface WebhookTarget {
  url: string;
  secret?: string;
}

/**
 * Deliver a webhook payload to a target URL.
 * Signs with HMAC-SHA256 when secret is provided.
 * Retries on failure (at-least-once delivery).
 */
export async function deliverWebhook(
  target: WebhookTarget,
  payload: WebhookPayload,
  deps: WebhookDelivererDeps = {},
): Promise<{ ok: boolean; attempt: number }> {
  const maxRetries = deps.maxRetries ?? DEFAULT_RETRY_ATTEMPTS;
  const result = await deliverWithSharedPackage(
    {
      url: target.url,
      payload,
      secret: target.secret,
      signatureHeader: RECFN_SIGNATURE_HEADER,
    },
    {
      fetch: deps.fetch,
      maxRetries,
      initialDelayMs: 1000,
    }
  );

  if (!result.ok) {
    const lastAttempt = result.attempts[result.attempts.length - 1];
    throw new Error(lastAttempt?.error ?? 'Webhook delivery failed');
  }

  return {
    ok: true,
    attempt: result.attempts.length,
  };
}
