    if (addresses.length === 0) {
      const failure = results.find((result) => result.status === 'rejected');
      throw failure?.reason ?? new Error(`DNS lookup returned no addresses for ${hostname}`);
    }
    return addresses;
  } finally {
    signal.removeEventListener('abort', cancel);
  }
