  return tenant ? { id: 'test-key', type: 'api-key', subject: { actorId: 'verified-' + tenant, actorType: 'api-key', tenantId: tenant }, scopes: ['userfn:feedback:write', 'userfn:feedback:read'] } : null;
} };
