export interface UserFnServiceOptions {
  database: Adapter;
  /** AuthFn's provider can be supplied here. Cookie authentication is not accepted by this API. */
  auth: AuthProvider;
  maxBodyBytes?: number;
  /** Explicit browser origins; credentials/cookies are never enabled. */
