## Development

### Running Tests

```bash
# Install dependencies
pip install -e ".[dev]"

# Run tests
pytest
```

## License

MIT

## Feedback delivery boundary

Use `await client.submit_feedback(FeedbackSubmission(...))`. Configure `UserFnOptions(feedback_service=service)` with an async `submit(submission, context)` method returning `FeedbackReceipt(id='stored-id', accepted=True)` after the backing service accepts the submission. The context contains `source='in_app'` and the current identity, or `None` after reset.

Missing configuration, invalid input, or a missing/negative/empty receipt raises an error; service exceptions propagate. `endpoint` and `api_key` alone do not configure this operation. The Python SDK previously had no feedback submission method.

This is a temporary injected service contract, not the specified HTTP/DB backend or proof of persistence. Authentication, durable storage, retries, feedback board/voting, and source integrations remain implementation requirements. Callers must not synthesize acceptance before their backing service accepts the submission.
/**
 * Core type definitions for the authentication abstraction layer
 */

type UnknownRecord = Record<string, unknown>;

export type AuthActorType = 'user' | 'api-key' | 'service';

/**
 * Actor information associated with an authenticated session.
 */
export interface AuthSubject {
  /** Unique identifier for the authenticated actor */
  actorId: string;

  /** Actor category (user, API key, service, etc.) */
  actorType: AuthActorType;

  /** Optional tenant/workspace identifier */
  tenantId?: string;

  /** Optional region identifier */
  regionId?: string;

  /** Optional canonical email for user actors */
  email?: string;

  /** Optional opaque subject attributes */
  attributes?: UnknownRecord;
}

// ============================================================================
// Authentication Session
// ============================================================================

/**
 * Authenticated session data returned by auth providers
 */
export interface AuthSession<TMetadata = any> {
  /** Unique identifier for the authenticated entity (user, API key, etc.) */
  id: string;

  /** Type of authentication (e.g., 'api-key', 'session', 'jwt', 'oauth') */
  type: string;

  /** Actor/subject represented by the session */
  subject: AuthSubject;

  /** Resource IDs this session has access to (e.g., project IDs, organization IDs) */
  resourceIds?: string[];

  /** Optional: Scopes or permissions */
  scopes?: string[];

  /** Optional: Satisfied auth methods */
  methods?: string[];

  /** Optional: Expiration timestamp */
  expiresAt?: Date;

  /** Optional: Additional metadata */
  metadata?: TMetadata;
}

// ============================================================================
// Auth Provider Interface
// ============================================================================

/**
 * Core authentication provider interface
 * All auth implementations must conform to this interface
