/**
 * Capability system for adapter feature detection
 */

import type { TransactionIsolation } from './types.js';

export interface AdapterCapabilities {
  // Supported data types
  types: {
    json: boolean;
    dates: boolean;
    booleans: boolean;
    bigint: boolean;
    uuid: boolean;
    enum: boolean;
  };

  // Supported operations
  operations: {
    batch: boolean; // createMany, updateMany, deleteMany
    upsert: boolean; // Upsert operation
    streaming: boolean; // Stream large datasets
    fulltext: boolean; // Full-text search
    returning: boolean; // RETURNING clause support
    strictUpdateNotFound?: boolean; // update() throws NotFoundError/canonical not-found on zero matched rows
  };

  // Transaction support
  transactions: {
    supported: boolean;
    nested: boolean; // Savepoints
    isolation?: TransactionIsolation[];
    /** Honors explicit per-call transaction isolation options. */
    configurableIsolation?: boolean;
  };

  // Performance characteristics
  performance: {
    maxBatchSize?: number;
    supportsJoins: boolean;
    supportsPreparedStatements: boolean;
  };

  // Schema capabilities
  schema: {
    migrations: boolean;
    constraints: boolean;
    indexes: boolean;
  };

  // Advanced features
  advanced: {
    customIdGeneration: boolean;
    numericIds: boolean;
    schemaNamespaces: boolean;
    customTypes: boolean;
  };
}

/**
 * Default capabilities - conservative defaults that work everywhere
 */
export const DEFAULT_CAPABILITIES: AdapterCapabilities = {
  types: {
    json: false,
    dates: true,
    booleans: true,
    bigint: false,
    uuid: false,
    enum: false,
  },
  operations: {
    batch: false,
    upsert: false,
