import { expect, it } from "vitest";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import Database from "better-sqlite3";
import { Kysely, SqliteDialect } from "kysely";
import { kyselyAdapter } from "@superfunctions/db/adapters";
import { DatabaseStorage, getWatchFnSchema } from "../../src/storage/database";
import { WatchFn } from "../../src/core/watch-fn";

it("persists ingested JSON through native SQLite close and reopen", async () => {
  const directory = await mkdtemp(join(tmpdir(), "watchfn-sqlite-"));
  let sql: Kysely<any> | undefined;
  let watch: WatchFn | undefined;
  const connect = () => {
    sql = new Kysely({ dialect: new SqliteDialect({ database: new Database(join(directory, "events.sqlite")) }) });
    return kyselyAdapter({ db: sql, dialect: "sqlite", schema: { watchfn_events: "watchfn_events" } });
  };
  try {
    let db = connect();
    let migration = sql!.schema.createTable("watchfn_events");
    for (const [name, field] of Object.entries(getWatchFnSchema().watchfn_events.fields)) {
      migration = migration.addColumn(name, "text", column => name === "id" ? column.primaryKey() : field.required ? column.notNull() : column);
    }
    await migration.execute();
    watch = new WatchFn({ name: "test", storage: "database", database: db, infra: { enabled: false } } as any);
    watch.start();
    const event = { name: "log", timestamp: "2026-10-20T00:00:00Z", traceId: "trace", ctx: { nested: [1, true, null, "文"] } };
    const response = await watch.httpRouter.handle(new Request("http://local/ingest", { method: "POST", body: JSON.stringify(event) }));
    expect(response.status).toBe(202);
    watch.stop();
    await sql!.destroy(); sql = undefined;
    db = connect();
    const storage = new DatabaseStorage(db);
    expect(await storage.getAll()).toEqual([event]);
    expect(await storage.query(value => value.traceId === "trace")).toEqual([event]);
    const rows = await sql!.selectFrom("watchfn_events").selectAll().execute();
    expect(typeof rows[0].payload).toBe("string");
    expect(JSON.parse(rows[0].payload)).toEqual(event);
    await sql!.schema.dropTable("watchfn_events").execute();
    await expect(storage.add(event)).rejects.toThrow();
  } finally {
    watch?.stop();
    if (sql) await sql.destroy();
    await rm(directory, { recursive: true, force: true });
  }
});
/**
 * Core type definitions for the adapter system
 */

import type { AdapterCapabilities } from './capabilities.js';

// ============================================================================
// Adapter Interface
// ============================================================================

export interface Adapter {
  // Metadata
  readonly id: string;
  readonly name: string;
  readonly version: string;
  readonly capabilities: AdapterCapabilities;

  // Core CRUD operations
  create<T = any>(params: CreateParams): Promise<T>;
  findOne<T = any>(params: FindOneParams): Promise<T | null>;
  findMany<T = any>(params: FindManyParams): Promise<T[]>;
  update<T = any>(params: UpdateParams): Promise<T>;
  delete(params: DeleteParams): Promise<void>;

  // Batch operations
  createMany<T = any>(params: CreateManyParams): Promise<T[]>;
  updateMany(params: UpdateManyParams): Promise<number>;
  deleteMany(params: DeleteManyParams): Promise<number>;

  // Advanced operations
  upsert<T = any>(params: UpsertParams): Promise<T>;
  count(params: CountParams): Promise<number>;

  // Transaction support
  transaction<R>(callback: (trx: TransactionAdapter) => Promise<R>, options?: { isolationLevel: TransactionIsolation }): Promise<R>;

  // Lifecycle management
  initialize(): Promise<void>;
  isHealthy(): Promise<HealthStatus>;
  close(): Promise<void>;

  // Schema management
  getSchemaVersion(namespace: string): Promise<number>;
  setSchemaVersion(namespace: string, version: number): Promise<void>;
  validateSchema(schema: TableSchema): Promise<ValidationResult>;

  // Optional: Schema generation for CLI
  createSchema?(params: CreateSchemaParams): Promise<SchemaCreation>;

  /** Raw CRUD for internal tables, bypasses ORM schema resolution */
  readonly internal: InternalCrud;
}

export interface TransactionAdapter extends Omit<Adapter, 'transaction' | 'close'> {
  commit(): Promise<void>;
  rollback(): Promise<void>;
}

export interface HealthStatus {
  healthy: boolean;
  connections?: {
    active: number;
    idle: number;
    max: number;
  };
  lastError?: Error;
  uptime: number;
}

// ============================================================================
import { defineConfig } from "vitest/config";
export default defineConfig({ test: { environment: "node", include: ["tests/storage/sqlite.acceptance.ts"] } });

