import type { BotFnIssueRoute, BugIssueLink } from "./types";

export const issueMarker = (id: string) => `<!-- watchfn-bug:${id} -->`;
export function issueBody(event: Record<string, any>, id: string): string {
  const report = event.report;
  return [report.description ?? "", ...(report.steps?.length ? ["Steps:", ...report.steps.map((step: string, i: number) => `${i + 1}. ${step}`)] : []),
    `Severity: ${report.severity}`, ...(report.tags?.length ? [`Tags: ${report.tags.join(", ")}`] : []), issueMarker(id)].join("\n\n");
}
const githubPath = (route: BotFnIssueRoute) => `/repos/${route.project.split("/").map(encodeURIComponent).join("/")}/issues`;
function githubLink(route: BotFnIssueRoute, value: any, id: string, expected?: string): BugIssueLink {
  if (!value || !Number.isSafeInteger(value.number) || value.number < 1 || (expected && String(value.number) !== expected) || value.pull_request || typeof value.body !== "string" || !value.body.includes(issueMarker(id))) throw new Error("Invalid issue receipt");
  const url = new URL(value.html_url);
  if (url.origin !== "https://github.com" || url.username || url.password || url.search || url.hash || url.pathname !== `/${route.project}/issues/${value.number}`) throw new Error("Invalid issue URL");
  return { issueId: String(value.number), issueUrl: url.toString() };
}
function linearLink(route: BotFnIssueRoute, value: any, id: string, expected?: string): BugIssueLink {
  if (!value || typeof value.id !== "string" || !/^[A-Za-z0-9_-]{1,128}$/.test(value.id) || (expected && value.id !== expected) || value.team?.id !== route.project || typeof value.description !== "string" || !value.description.includes(issueMarker(id)) || typeof value.identifier !== "string" || !/^[A-Za-z0-9]+-\d+$/.test(value.identifier)) throw new Error("Invalid issue receipt");
  const url = new URL(value.url);
  const segments = url.pathname.split("/");
  if (url.origin !== "https://linear.app" || url.username || url.password || url.search || url.hash || segments.length < 4 || !segments[1] || segments[2] !== "issue" || segments[3] !== value.identifier) throw new Error("Invalid issue URL");
  return { issueId: value.id, issueUrl: url.toString() };
}

/** No automatic create retries: a transport failure can follow a committed remote side effect. */
export async function createBotFnIssue(route: BotFnIssueRoute, event: Record<string, any>, id: string, signal: AbortSignal): Promise<BugIssueLink> {
  const description = issueBody(event, id);
  if (route.target === "github") {
    const issue = await route.client.request(githubPath(route), { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ title: event.report.title, body: description }), signal, redirect: "error" });
    return githubLink(route, issue, id);
  }
  const result = await route.client.request<any>(`mutation WatchFnCreateIssue($teamId: String!, $title: String!, $description: String!) {
    issueCreate(input: {teamId: $teamId, title: $title, description: $description}) { success issue { id identifier url description team { id } } }
  }`, { teamId: route.project, title: event.report.title, description });
  if (result?.issueCreate?.success !== true) throw new Error("Issue was not acknowledged");
  return linearLink(route, result.issueCreate.issue, id);
}

/** Verify an operator-selected issue against the trusted destination and the stable report marker. */
export async function verifyBotFnIssue(route: BotFnIssueRoute, issueId: string, id: string, signal: AbortSignal): Promise<BugIssueLink> {
  if (route.target === "github") {
    if (!/^[1-9]\d{0,14}$/.test(issueId)) throw new Error("Invalid issue ID");
    return githubLink(route, await route.client.request(`${githubPath(route)}/${issueId}`, { signal, redirect: "error" }), id, issueId);
  }
  if (!/^[A-Za-z0-9_-]{1,128}$/.test(issueId)) throw new Error("Invalid issue ID");
  const result = await route.client.request<any>(`query WatchFnVerifyIssue($id: String!) { issue(id: $id) { id identifier url description team { id } } }`, { id: issueId });
  return linearLink(route, result?.issue, id, issueId);
}
import { expect, it } from "vitest";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import Database from "better-sqlite3";
import { Kysely, SqliteDialect } from "kysely";
import { kyselyAdapter } from "@superfunctions/db/adapters";
import { DatabaseStorage, getWatchFnSchema } from "../../src/storage/database";
import { WatchFn } from "../../src/core/watch-fn";

it("persists ingested JSON through native SQLite close and reopen", async () => {
  const directory = await mkdtemp(join(tmpdir(), "watchfn-sqlite-"));
  let sql: Kysely<any> | undefined;
  let watch: WatchFn | undefined;
  const connect = () => {
    sql = new Kysely({ dialect: new SqliteDialect({ database: new Database(join(directory, "events.sqlite")) }) });
    return kyselyAdapter({ db: sql, dialect: "sqlite", schema: { watchfn_events: "watchfn_events" } });
  };
  try {
    let db = connect();
    let migration = sql!.schema.createTable("watchfn_events");
    for (const [name, field] of Object.entries(getWatchFnSchema().watchfn_events.fields)) {
      migration = migration.addColumn(name, "text", column => name === "id" ? column.primaryKey() : field.required ? column.notNull() : column);
    }
    await migration.execute();
    watch = new WatchFn({ name: "test", storage: "database", database: db, infra: { enabled: false } } as any);
    watch.start();
    const event = { name: "log", timestamp: "2026-10-20T00:00:00Z", traceId: "trace", ctx: { nested: [1, true, null, "文"] } };
    const response = await watch.httpRouter.handle(new Request("http://local/ingest", { method: "POST", body: JSON.stringify(event) }));
    expect(response.status).toBe(202);
    watch.stop();
    await sql!.destroy(); sql = undefined;
    db = connect();
    const storage = new DatabaseStorage(db);
    expect(await storage.getAll()).toEqual([event]);
    expect(await storage.query(value => value.traceId === "trace")).toEqual([event]);
    const rows = await sql!.selectFrom("watchfn_events").selectAll().execute();
    expect(typeof rows[0].payload).toBe("string");
    expect(JSON.parse(rows[0].payload)).toEqual(event);
    await sql!.schema.dropTable("watchfn_events").execute();
    await expect(storage.add(event)).rejects.toThrow();
  } finally {
    watch?.stop();
    if (sql) await sql.destroy();
    await rm(directory, { recursive: true, force: true });
  }
});
import { afterEach, describe, expect, it, vi } from "vitest";
import { WatchFn } from "../../src/core/watch-fn";

const active: WatchFn[] = [];
function setup(options: Record<string, unknown> = {}) {
  const insertEvent = vi.fn(async (_event: unknown) => {});
  const watch = new WatchFn({ name: "ingest-test", storage: "database", database: {
    insertEvent, queryEvents: async () => [],
  }, infra: { enabled: false }, ...options } as any);
  active.push(watch);
  watch.start();
  return { watch, insertEvent };
}
function request(body: unknown, headers?: HeadersInit) {
  return new Request("http://localhost/ingest", { method: "POST", headers, body: JSON.stringify(body) });
}
afterEach(() => { for (const watch of active.splice(0)) watch.stop(); });

describe("HTTP ingestion", () => {
  it("preserves the complete envelope in all supported batch shapes", async () => {
    const { watch, insertEvent } = setup();
    const event = { name: "log", type: "log", v: 0, timestamp: "2026-10-20T00:00:00Z",
      message: "hello", level: "info", traceId: "abc", requestId: "req", ctx: { x: 1 }, tags: ["test"] };
    for (const body of [event, [event], { events: [event] }]) {
      const result = await watch.httpRouter.handle(request(body));
      expect(result.status).toBe(202);
      expect(await result.json()).toEqual({ accepted: 1 });
    }
    expect(insertEvent.mock.calls.map(([value]) => value)).toEqual([event, event, event]);
  });

  it("does not acknowledge until every persistence promise completes", async () => {
    const { watch, insertEvent } = setup();
    let release!: () => void;
    insertEvent.mockImplementationOnce(() => new Promise<void>(resolve => { release = resolve; }));
    let settled = false;
    const response = watch.httpRouter.handle(request([{ name: "first" }, { name: "second" }]))
      .then(result => { settled = true; return result; });
    await vi.waitFor(() => expect(insertEvent).toHaveBeenCalledTimes(1));
    expect(settled).toBe(false);
    release();
    expect((await response).status).toBe(202);
    expect(insertEvent).toHaveBeenCalledTimes(2);
  });

  it("returns 503 on storage rejection without exposing the error", async () => {
    const { watch, insertEvent } = setup();
    insertEvent.mockRejectedValueOnce(new Error("secret database credentials"));
    const result = await watch.httpRouter.handle(request({ name: "event" }));
    expect(result.status).toBe(503);
