    const surveys = this.surveys.getEligibleSurveys(type, context, user);
    if (surveys.length > 0) {
      const survey = surveys[0];
      this.renderer?.renderSurvey(
        survey,
        (response) => {
          this.surveys.trackResponse(response);
          // TODO: emit to watchfn
        },
        () => {
