  }

  getConfigRefreshStatus() {
    return this.configRefreshLoop?.status() ?? { running: false, consecutiveFailures: 0 };
  }

  setFlags(flags: FlagConfig[]) {
    this.flags.setFlags(flags);
    this.configService?.invalidate();
