  constructor(limit: number = 1000) {
    this.limit = limit;
  }

  add(event: any) {
    this.events.push(event);
    if (this.events.length > this.limit) {
      this.events.shift();
    }
  }

  query(filter: (event: any) => boolean) {
    return this.events.filter(filter);
