from typing import Optional, List

from .core import Logger, create_logger
from .pipeline import redact, enrich_context, sample, with_request_ids
from .sinks import SinkConsole, SinkHttp
from .types import LogCorrelation, ErrorHandler, LogLevel, LogEvent, Sink, PipelineStage

def dev_logger(name: str = "app") -> Logger:
    """
    Create a development logger with pretty console output and debug level.
    """
    return create_logger(
        name=name,
        level="debug",
        sinks=[SinkConsole(json=False, color=True)],
    )

def server_logger(
    name: str,
    url: Optional[str] = None,
    level: LogLevel = "info"
) -> Logger:
    """
    Create a server logger with JSON output and optional HTTP sink.
    """
    sinks: List[Sink] = [SinkConsole(json=True, color=False)]
    if url:
        sinks.append(SinkHttp(url=url))

    return create_logger(
        name=name,
        level=level,
        sinks=sinks,
    )

__all__ = [
    "LogCorrelation",
    "ErrorHandler",
    "Logger",
    "create_logger",
    "dev_logger",
    "server_logger",
    "SinkConsole",
    "SinkHttp",
    "redact",
    "enrich_context",
    "sample",
    "with_request_ids",
    "LogLevel",
    "LogEvent",
    "Sink",
    "PipelineStage",
]
import sys
from typing import Any, Dict, List, Literal, Optional, Protocol, Union, Callable, runtime_checkable

if sys.version_info >= (3, 11):
    from typing import NotRequired, TypedDict
else:
    from typing_extensions import NotRequired, TypedDict


LogLevel = Literal["trace", "debug", "info", "warn", "error", "fatal"]

LOG_LEVEL_VALUES: Dict[LogLevel, int] = {
    "trace": 0,
    "debug": 1,
    "info": 2,
    "warn": 3,
    "error": 4,
    "fatal": 5,
}

DEFAULT_VERSION = "0"

class LogCorrelation(TypedDict, total=False):
    traceId: str
    spanId: str
    requestId: str
    userId: str
    tenantId: str


class LogEvent(TypedDict):
    ts: str  # ISO8601 timestamp
    level: LogLevel
    msg: str
    name: str
    ctx: NotRequired[Dict[str, Any]]
    tags: NotRequired[List[str]]
    traceId: NotRequired[str]
    spanId: NotRequired[str]
    requestId: NotRequired[str]
    userId: NotRequired[str]
    tenantId: NotRequired[str]
    version: str

ErrorHandler = Callable[[BaseException, Dict[str, str]], None]

PipelineStage = Callable[[LogEvent], Optional[LogEvent]]

@runtime_checkable
class Sink(Protocol):
    def __call__(self, batch: List[LogEvent]) -> Any:
        ...

    # flush is optional in TS but Protocol doesn't support optional methods well.
    # We can check with hasattr at runtime.
