def default_now() -> datetime:
    return datetime.now(timezone.utc)

def get_default_level() -> LogLevel:
    env = os.environ.get("ENV", os.environ.get("NODE_ENV", "development"))
    return "info" if env == "production" else "debug"

class _ErrorReporter:
    def __init__(self, callback: Optional[ErrorHandler]) -> None:
        self.callback = callback
        self.reporting = False

    def report(self, error: BaseException, context: Dict[str, str]) -> None:
        if self.reporting:
            return
        self.reporting = True
        try:
            if self.callback is not None:
                try:
                    self.callback(error, context)
                except Exception:
                    print("[logfn internal error] error callback failed", file=sys.stderr)
            else:
                print(f"[logfn internal error] {context}: {type(error).__name__}", file=sys.stderr)
        finally:
            self.reporting = False


class _DeliveryState:
    def __init__(self, reporter: _ErrorReporter) -> None:
        self.reporter = reporter
        self.contexts: Dict[asyncio.Future[Any], Dict[str, str]] = {}
        self.pending: Set[asyncio.Future[Any]] = set()
        self.error: Optional[BaseException] = None

    def completed(self, task: asyncio.Future[Any]) -> None:
        self.pending.discard(task)
        context = self.contexts.pop(task, {"sink": "unknown"})
        error = asyncio.CancelledError() if task.cancelled() else task.exception()
        if error is not None:
            if self.error is None:
                self.error = error
            self.reporter.report(error, context)


class Logger:
    def __init__(
        self,
        name: str,
        sinks: List[Sink],
        level: Optional[LogLevel] = None,
        pipeline: Optional[List[PipelineStage]] = None,
        now: Optional[Callable[[], datetime]] = None,
        base_context: Optional[Dict[str, Any]] = None,
        base_tags: Optional[List[str]] = None,
        on_error: Optional[ErrorHandler] = None,
        correlation: Optional[LogCorrelation] = None,
    ):
        self._reporter = _ErrorReporter(on_error)
        self._delivery = _DeliveryState(self._reporter)
        self.name = name
        self.sinks = sinks
        self.level = level or get_default_level()
        self.pipeline = pipeline or []
        self.now = now or default_now
        self.base_context = base_context or {}
        self.base_tags = base_tags or []
        self.correlation: LogCorrelation = {**(correlation or {})}

        if not sinks:
            # We don't throw here to avoid breaking apps, but it's bad practice
            print("Warning: Logger created without sinks", file=sys.stderr)

    def should_log(self, level: LogLevel) -> bool:
        return LOG_LEVEL_VALUES[level] >= LOG_LEVEL_VALUES[self.level]

    def _log(
        self,
        level: LogLevel,
        msg: str,
        ctx: Optional[Dict[str, Any]] = None,
        tags: Optional[List[str]] = None,
        **kwargs: Any,
    ) -> None:
        if not self.should_log(level):
            return

        # Merge kwargs into ctx for convenience: logger.info("msg", user_id="1")
        if kwargs:
            ctx = {**(ctx or {}), **kwargs}

        event: LogEvent = {
            "ts": self.now().isoformat(),
            "level": level,
            "msg": msg,
            "name": self.name,
            "version": DEFAULT_VERSION,
        }

        if "traceId" in self.correlation:
            event["traceId"] = self.correlation["traceId"]
        if "spanId" in self.correlation:
            event["spanId"] = self.correlation["spanId"]
        if "requestId" in self.correlation:
            event["requestId"] = self.correlation["requestId"]
        if "userId" in self.correlation:
            event["userId"] = self.correlation["userId"]
        if "tenantId" in self.correlation:
            event["tenantId"] = self.correlation["tenantId"]

        # Merge context
        merged_ctx = {**self.base_context}
        if ctx:
            merged_ctx.update(ctx)
        if merged_ctx:
            event["ctx"] = merged_ctx

        # Merge tags
        merged_tags = list(self.base_tags)
        if tags:
            merged_tags.extend(tags)
        if merged_tags:
            event["tags"] = merged_tags

        # Pipeline
        current_event: Optional[LogEvent] = event
        for stage in self.pipeline:
            try:
                if current_event:
                    current_event = stage(current_event)
            except Exception as e:
                self._reporter.report(e, {"stage": getattr(stage, "__name__", type(stage).__name__)})

        if not current_event:
            return

        # Sinks
        batch = [bound_event(current_event)]
        for sink in self.sinks:
            try:
                res = sink(batch)
                if inspect.isawaitable(res):
                    try:
                        asyncio.get_running_loop()
                    except RuntimeError:
                        if inspect.iscoroutine(res):
                            res.close()
                        error = RuntimeError("Async sink requires a running event loop")
/**
 * Core type definitions for LogFn
 */

// ============================================================================
// Log Levels
// ============================================================================

/**
 * Log severity levels
 */
export type LogLevel = "trace" | "debug" | "info" | "warn" | "error" | "fatal";

/**
 * Numeric representation of log levels for comparison
 */
export const LOG_LEVEL_VALUES: Record<LogLevel, number> = {
  trace: 0,
  debug: 1,
  info: 2,
  warn: 3,
  error: 4,
  fatal: 5,
};

// ============================================================================
// Log Event Schema
// ============================================================================

/**
 * Structured log event matching v0 spec
 */
export interface LogEvent {
  /** RFC3339 timestamp with milliseconds */
  ts: string;

  /** Log severity level */
  level: LogLevel;

  /** Human-readable message */
  msg: string;

  /** Logger/component name */
  name: string;

  /** Arbitrary context (shallow serializable values only) */
  ctx?: Record<string, unknown>;

  /** Tags for categorization (<= 20 entries) */
  tags?: string[];

  /** W3C TraceContext trace ID */
  traceId?: string;

  /** W3C TraceContext span ID */
  spanId?: string;

  /** Request correlation ID */
  requestId?: string;

  /** User identifier (may be redacted) */
  userId?: string;

  /** Tenant identifier (may be redacted) */
  tenantId?: string;

  /** Schema version */
  version: string;
}

// ============================================================================
// Pipeline & Sinks
// ============================================================================

/**
 * Pipeline stage processes and optionally modifies events
 * Returns null to drop the event (sampling)
 */
export type PipelineStage = (event: LogEvent) => LogEvent | null;

/**
 * Sink receives batches of log events and sends them to a destination
 */
export interface Sink {
  /** Process a batch of log events */
  (batch: LogEvent[]): Promise<void> | void;

  /** Optional: flush any buffered events */
  flush?(): Promise<void>;
}

// ============================================================================
// Logger Configuration
// ============================================================================

/**
 * Logger configuration options
 */
export type LogCorrelation = Pick<LogEvent, "traceId" | "spanId" | "requestId" | "userId" | "tenantId">;

export interface LoggerOptions {
  /** Correlation fields emitted at the top level of each event. */
  correlation?: LogCorrelation;
  /** Receives pipeline and sink failures; callback failures never escape logging. */
  onError?: ErrorHandler;

  /** Logger/component name (required) */
  name: string;

  /** Minimum log level to emit (default: 'info' in prod, 'debug' in dev) */
  level?: LogLevel;

  /** Pipeline stages to apply in order (default: empty) */
  pipeline?: PipelineStage[];

  /** Sinks to send events to (at least one required) */
  sinks: Sink[];

  /** Custom timestamp function for testing (default: () => new Date()) */
  now?: () => Date;

  /** Base context to include in all events */
  baseContext?: Record<string, unknown>;

  /** Base tags to include in all events */
  baseTags?: string[];
}

/**
 * Options for creating child loggers
 */
export interface ChildLoggerOptions {
  /** Merge correlation fields with the parent. */
  correlation?: LogCorrelation;
  /** Override logger name */
  name?: string;

  /** Override log level */
  level?: LogLevel;

  /** Additional context to merge */
  ctx?: Record<string, unknown>;

  /** Additional tags to merge */
  tags?: string[];
}

// ============================================================================
// Validation Constants
// ============================================================================

/**
 * Maximum event size in bytes after serialization
 */
export const MAX_EVENT_SIZE = 64 * 1024; // 64KB

/**
 * Maximum number of tags per event
 */
export const MAX_TAGS = 20;

/**
 * Default schema version
 */
export const DEFAULT_VERSION = "0";

// ============================================================================
// Utility Types
// ============================================================================

/**
 * Internal error handler for pipeline/sink failures
 */
export type ErrorHandler = (
  error: Error,
  context: { stage?: string; sink?: string }
) => void;

/**
 * Serialization result
 */
export interface SerializationResult {
  event: LogEvent;
  truncated: boolean;
}
