  }

  /** Stop collection and await delivery. After failure, close/flush can be retried. */
  close(): Promise<void> {
    this.closed = true;
    for (const cancel of this.statusReadCancels) cancel();
    for (const dispose of this.disposers.splice(0)) dispose();
