    case 'DOWNLOAD_EXISTS':
      return 409;
    case 'DOWNLOAD_TOO_LARGE':
      return 413;
    case 'RATE_LIMITED':
      return 429;
    case 'PROVIDER_ERROR':
      return 502;
    case 'PROVIDER_UNAVAILABLE':
      return 503;
    case 'UPSTREAM_TIMEOUT':
      return 504;
    default:
      return 500;
  }
}

